create table if not exists "server_plugin_scripts" ("plugin_id" text not null primary key, "source" text not null, "enabled" integer default 0 not null check (enabled in (0, 1)), "interval_hours" integer default 1 not null check (interval_hours between 1 and 168), "next_run_at" integer not null, "created_at" integer not null, "updated_at" integer not null, constraint "fk_server_plugin_scripts_plugin_id" foreign key ("plugin_id") references "server_plugin_installations" ("plugin_id") on delete cascade);
create index if not exists "idx_server_plugin_scripts_due" on "server_plugin_scripts" ("enabled", "next_run_at" asc)
